#!/usr/bin/env node
// Blocks AI-attribution traces in commit messages and author identities.
//
// Why this exists: this repository is authored by its owner alone. AI tools
// that help with the code must never show up in the history — no AI
// co-author lines, no "generated by" markers, no AI account as author.
// The check targets attribution only: a commit *about* AI features (the
// quick-add parser, on-device intelligence) is of course fine.
//
// Usage:
//   node scripts/check-commit-message.mjs <message-file>   (commit-msg hook)
//   node scripts/check-commit-message.mjs --range <range>  (pre-push backstop)
//
// Exit code 1 with an explanation when a trace is found, 0 otherwise.

import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

const AI_NAMES =
  "claude|anthropic|chatgpt|openai|copilot|codex|gemini|cursor|aider|codeium|windsurf|devin|cody";
const AI_EMAIL =
  "(anthropic\\.com|openai\\.com|claude@|chatgpt@|copilot@|cursor@)";

const MESSAGE_RULES = [
  {
    re: new RegExp(`^\\s*co-authored-by:[^\\n]*(${AI_NAMES}|${AI_EMAIL})`, "im"),
    why: "AI co-author line",
  },
  {
    re: new RegExp(`^\\s*signed-off-by:[^\\n]*(${AI_NAMES}|${AI_EMAIL})`, "im"),
    why: "AI sign-off line",
  },
  {
    re: new RegExp(`generated (with|by)[^\\n]*(${AI_NAMES}|\\bai\\b)`, "i"),
    why: '"generated by/with" AI marker',
  },
  { re: /\bai-generated\b/i, why: '"AI-generated" marker' },
  { re: /🤖/, why: "robot emoji marker" },
];

const IDENTITY_RULES = [
  {
    re: new RegExp(`(${AI_NAMES})`, "i"),
    why: "AI name in author/committer identity",
  },
  { re: new RegExp(AI_EMAIL, "i"), why: "AI vendor email in identity" },
];

function checkMessage(message) {
  const hits = [];
  for (const rule of MESSAGE_RULES) {
    if (rule.re.test(message)) hits.push(rule.why);
  }
  return hits;
}

function fail(hits, where) {
  console.error(`Commit trace check failed (${where}):`);
  for (const hit of hits) console.error(`  - ${hit}`);
  console.error(
    "This repository does not carry AI attribution in its history. " +
      "Remove the line/marker and commit again.",
  );
  process.exit(1);
}

const args = process.argv.slice(2);

if (args[0] === "--range") {
  const range = args[1];
  if (!range) {
    console.error("usage: check-commit-message.mjs --range <git-range>");
    process.exit(2);
  }
  let log;
  try {
    log = execFileSync(
      "git",
      ["log", "--format=%an%x00%ae%x00%cn%x00%ce%x00%B%x1e", range],
      { encoding: "utf8" },
    );
  } catch {
    // No commits in range (or no such ref): nothing to check.
    process.exit(0);
  }
  for (const entry of log.split("\x1e")) {
    const trimmed = entry.trim();
    if (!trimmed) continue;
    const [an = "", ae = "", cn = "", ce = "", ...rest] = trimmed.split("\x00");
    const message = rest.join("\x00");
    const hits = checkMessage(message);
    for (const identity of [an, ae, cn, ce]) {
      for (const rule of IDENTITY_RULES) {
        if (rule.re.test(identity)) hits.push(rule.why);
      }
    }
    if (hits.length) fail(hits, `commit in ${range}: ${message.split("\n")[0]}`);
  }
  process.exit(0);
}

const file = args[0];
if (!file) {
  console.error("usage: check-commit-message.mjs <message-file>");
  process.exit(2);
}
const hits = checkMessage(readFileSync(file, "utf8"));
if (hits.length) fail(hits, "commit message");
